 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.leadcomList =[]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil50100' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.upd_attachFiles = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_attachFiles') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_attachFiles"]');
        scwin.upd_attachFiles_2 = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_attachFiles_2') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_attachFiles_2"]');
        scwin.upd_attachFiles_3 = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_attachFiles_3') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_attachFiles_3"]');
        scwin.upd_attachFiles_4 = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_attachFiles_4') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_attachFiles_4"]');
        scwin.bzRegNo = '' + dma_detailData.get("bz_reg_no") + '';
        scwin.delListAgnccomMbr = delListAgnccomMbr;
        scwin.checkListAgnccom = checkListAgnccom;
        scwin.checkIsurCd = scwin.tx_checkIsurCd;
        scwin.chkId = scwin.tx_chkId;
        await scwin.init_rowCopy();
        scwin.init_attrReals();
        scwin.init_conds();
        scwin.init_sessionFill();
        await scwin.init_loadList();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil50100.onpageload' });
    }
};

