/**
 * @method
 * @name setLeadcomVars
 * @description set Leadcom Vars 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setLeadcomVars = async function () {
    for (let __i = 0; __i < (function(){ throw 'unresolved:list:leadcomList'; })(); __i++) {
        scwin.leadcomList[(function(){ throw 'unresolved:list:leadcomList'; })()] = (String(((function(){ throw 'unresolved:list:leadcomList'; })()) == null ? '' : ((function(){ throw 'unresolved:list:leadcomList'; })())).indexOf('$' + '{') >= 0 ? '' : String(((function(){ throw 'unresolved:list:leadcomList'; })()) == null ? '' : ((function(){ throw 'unresolved:list:leadcomList'; })())));
    }
    for (let i = 0; i < scwin.leadcomList.length; i++) {
        if (i !== 0) {
            await scwin.addListAgnccomMbr(i - 1);
        }
        if (i === 0) {
            $c.util.getComponent("slc_listAgnccomMbrNo").setValue(scwin.leadcomList[i]);
        } else {
            $c.util.getComponent('slc_listAgnccomMbrNo')[i].value = scwin.leadcomList[i];
        }
    }
};

