async function checkListAgnccom(cObj) {
    const obj = form[cObj.name];
    const len = obj.length;
    if (len < 40) {
        for (let i = 0; i < len; i++) {
            if (obj[i] !== cObj) {
                if (obj[i].value === cObj.value) {
                    await $c.win.alert('이미 선택하신 상장주선인 입니다.');
                    cObj.value = '';
                }
            }
        }
    }
}

/**
 * @method
 * @name setLength
 * @description set Length 처리
 * @param {Object} obj 컴포넌트
 * @param {*} tdname tdname
 * @param {*} maxLength maxLength
 * @returns {void}
 * @hidden N
 */
scwin.setLength = function (obj, tdname, maxLength) {
    const strLength = scwin.calBytes(obj);
    ($c.util.getComponent(tdname) && $c.util.getComponent(tdname).setValue) ? $c.util.getComponent(tdname).setValue("  (" + strLength + "/" + maxLength + ")") : (($c.util.getComponent(tdname) && $c.util.getComponent(tdname).setText) ? $c.util.getComponent(tdname).setText("  (" + strLength + "/" + maxLength + ")") : (console.warn('[sdd] 값 쓰기 미지원 컴포넌트: ' + tdname), void ("  (" + strLength + "/" + maxLength + ")")));
};

/**
 * @method
 * @name calBytes
 * @description cal Bytes 처리
 * @param {String} str str
 * @returns {void}
 * @hidden N
 */
scwin.calBytes = function (str) {
    let tcount = 0;
    const tmpStr = new String(str);
    const temp = tmpStr.length;
    let onechar;
    for (let k = 0; k < temp; k++) {
        onechar = tmpStr.charAt(k);
        if (escape(onechar).length > 4) {
            tcount += 2;
        } else {
            if (escape(onechar) === '%0A') {
                tcount += 2;
            } else {
                tcount += 1;
            }
        }
    }
    return tcount;
};

/**
 * @method
 * @name estimateCounter
 * @description estimate Counter 처리
 * @param {Object} obj 컴포넌트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.estimateCounter = async function (obj) {
    if (scwin.calBytes(obj.getValue()) > 2000) {
        await $c.win.alert('한글 1000자 이하, 숫자/영문 2000자 이하까지만 입력이 가능합니다.');
        obj.focus();
        return;
    }
};

/**
 * @method
 * @name selectCorp
 * @description select Corp 처리
 * @returns {void}
 * @hidden N
 */
scwin.selectCorp = function () {
    if ($corpOptionList == null) {
        $corpOptionList = $("#slc_prelmInvstgComTpCd").children("option");
    }
    const $tempOptionList = $corpOptionList;
    if ($c.util.getComponent('slc_ldMktTpCd').getValue() === "1") {
        for (i = $tempOptionList.length - 1; i >= 0; i--) {
            const optionValue = $($tempOptionList[i]).val();
            if (optionValue === "7" || optionValue === "6" || optionValue === "1") {
                $($tempOptionList[i]).remove();
                continue;
            }
        }
    } else {
        $("#slc_prelmInvstgComTpCd").children("option").remove();
        (console.error('[sdd] #slc_prelmInvstgComTpCd append() 무동작 — 셀렉트박스 바깥 div 에 붙어 목록에 안 닿는다(표준은 addItem(값, 라벨)) — 이 꼴은 자동 전환 대상이 아니다'), $("#slc_prelmInvstgComTpCd")).append($corpOptionList);
    }
};

